import { useMemo, useRef } from 'react'
import { type LayoutChangeEvent, PanResponder } from 'react-native'
import { isWeb } from 'tamagui/unstyled'

const clamp01 = (value: number) => Math.min(1, Math.max(0, value))

export interface ColorDragOptions {
  disabled: boolean
  /** The pointer's place in the surface, from 0 to 1 on each axis. */
  onDrag: (x: number, y: number) => void
  /** The press or drag ended. */
  onEnd: () => void
}

type Pointer = {
  button: number
  clientX: number
  clientY: number
  pointerId: number
  currentTarget: HTMLElement
  preventDefault: () => void
}

/**
 * Press-and-drag on a color surface. Web uses pointer events with capture, so
 * the drag continues outside the surface; native uses a PanResponder that
 * keeps the gesture from a sheet or scroll view around it. Children of the
 * surface must not take touches (`pointerEvents="none"`): native positions are
 * relative to the view that was touched.
 */
export function useColorDrag(options: ColorDragOptions) {
  const handlers = useRef(options)
  handlers.current = options
  const dragging = useRef(false)
  // Native: the surface size from onLayout and where the touch started.
  const size = useRef({ width: 0, height: 0 })
  const origin = useRef({ x: 0, y: 0 })

  const native = useMemo(() => {
    if (isWeb) return null
    const report = (x: number, y: number) => {
      const { width, height } = size.current
      if (width > 0 && height > 0) handlers.current.onDrag(clamp01(x / width), clamp01(y / height))
    }
    const end = () => {
      if (!dragging.current) return
      dragging.current = false
      handlers.current.onEnd()
    }
    return PanResponder.create({
      onStartShouldSetPanResponder: () => !handlers.current.disabled,
      onMoveShouldSetPanResponder: () => !handlers.current.disabled,
      // Keep the drag when a sheet or scroll view around the surface asks for it.
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: (event) => {
        dragging.current = true
        origin.current = { x: event.nativeEvent.locationX, y: event.nativeEvent.locationY }
        report(origin.current.x, origin.current.y)
      },
      onPanResponderMove: (_, gesture) =>
        report(origin.current.x + gesture.dx, origin.current.y + gesture.dy),
      onPanResponderRelease: end,
      onPanResponderTerminate: end,
    })
  }, [])

  if (native) {
    return {
      surface: {
        ...native.panHandlers,
        onLayout: (event: LayoutChangeEvent) => {
          size.current = event.nativeEvent.layout
        },
      },
      // For a view around the surface. During a drag it claims each move
      // first, so a sheet further up is never asked: Tamagui's Sheet marks
      // itself as dragging when asked about a vertical move, even though the
      // surface keeps the gesture, and then stays open when told to close.
      guard: { onMoveShouldSetResponder: () => dragging.current },
    }
  }

  const report = (event: Pointer) => {
    const rect = event.currentTarget.getBoundingClientRect()
    if (rect.width > 0 && rect.height > 0) {
      handlers.current.onDrag(
        clamp01((event.clientX - rect.left) / rect.width),
        clamp01((event.clientY - rect.top) / rect.height),
      )
    }
  }
  const end = (event: Pointer) => {
    if (!dragging.current) return
    dragging.current = false
    event.currentTarget.releasePointerCapture?.(event.pointerId)
    handlers.current.onEnd()
  }
  return {
    surface: {
      onPointerDown: (event: Pointer) => {
        if (handlers.current.disabled || event.button !== 0) return
        // No text selection while dragging. That also skips the focus a press
        // would give, so focus the surface for the arrow keys.
        event.preventDefault()
        event.currentTarget.focus()
        event.currentTarget.setPointerCapture?.(event.pointerId)
        dragging.current = true
        report(event)
      },
      onPointerMove: (event: Pointer) => {
        if (dragging.current) report(event)
      },
      onPointerUp: end,
      onPointerCancel: end,
    },
    guard: null,
  }
}

import { colorTokens } from '@advui/theme'
import { type HSVA, fromHsv, parseColor, toHex, toHsv, withAlpha } from '@advui/utils'
import type { ColorTokens } from 'tamagui/unstyled'

// The spectrum, its white and black ends and the transparency grid are the
// colors being picked, not theme roles, so they stay the same in every theme.
export const WHITE = colorTokens.white
export const BLACK = colorTokens.black
export const CLEAR_WHITE = withAlpha(WHITE, 0)
export const CLEAR_BLACK = withAlpha(BLACK, 0)
/** The darker squares of the transparency grid, over white. */
export const CHECKER = withAlpha(BLACK, 0.12)
/** Outline around a thumb's white ring, so it shows on white too. */
export const THUMB_RING = withAlpha(BLACK, 0.45)

/** A computed color for a color prop, which otherwise takes theme keys. */
export const rawColor = (color: string) => color as ColorTokens

/** Thumb diameter (px), with its outline. */
export const THUMB = 18
/** Side of one square of the transparency grid (px). */
export const CHECKER_CELL = 4

export const hueGradient = `linear-gradient(to right, ${[0, 60, 120, 180, 240, 300, 360]
  .map((h) => fromHsv({ h, s: 1, v: 1 }))
  .join(', ')})`

/** `#rrggbb`, or `#rrggbbaa` when `alpha` is on and the color is translucent. */
export const formatColor = (hsv: HSVA, alpha: boolean) => fromHsv(alpha ? hsv : { ...hsv, a: 1 })

/**
 * Reads a typed or passed color: hex with or without `#`, `rgb()` or
 * `hsl()`. Null when it is not a color.
 */
export function readColor(input: string) {
  const text = input.trim()
  return parseColor(/^[0-9a-f]{3,8}$/i.test(text) ? `#${text}` : text)
}

/**
 * The HSV of a new value. HSV has more points than hex: every hue is the
 * same black or gray, so a hue (and the saturation of black) that the color
 * does not decide stays where it was. A value that is not a color keeps `prev`.
 */
export function hsvFrom(value: string, prev: HSVA): HSVA {
  const rgba = readColor(value)
  if (!rgba) return prev
  if (toHex(rgba) === fromHsv(prev)) return prev
  const next = toHsv(rgba)
  return {
    h: next.s === 0 || next.v === 0 ? prev.h : next.h,
    s: next.v === 0 ? prev.s : next.s,
    v: next.v,
    a: next.a,
  }
}

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export const focusRing = {
  outlineColor: 'focus-visible:ring',
  outlineStyle: 'focus-visible:solid',
  outlineWidth: 'focus-visible:2px',
  outlineOffset: 'focus-visible:2px',
} as const

/** Screen reader actions on native. */
export type AccessibilityActionEvent = { nativeEvent: { actionName: string } }

